import {stages as legacy} from './course.js';

// Stable IDs are independent of presentation order; v1 stages are never rewritten.
const chapter=(id,title,goal,body,terms,example,steps,solo,error,quiz,notes,fingers)=>({id,title,goal,body,terms,example,steps,solo,error,quiz,notes,fingers});
const q=(question,options,answer,explanation)=>({question,options,answer,explanation});
const old=(s,c)=>legacy[s-1].lessons[c].body;
export const curriculum=[
{id:'foundation',number:1,title:'Orientasi dan fondasi',requires:[],legacy:1,criteria:'Temukan nada di tiga register; mainkan pola lima nada dengan tiap tangan; pertahankan pulsa; jelaskan posisi nyaman.',chapters:[
chapter('instrument','Instrumen, pedal, dan tubuh yang nyaman','Membedakan instrumen dan menyiapkan tempat bermain.',[
'Piano akustik menghasilkan bunyi ketika palu memukul senar. Tuts, mekanisme palu, senar, damper (peredam), dan papan suara bekerja bersama. Piano digital mengubah input tuts menjadi rekaman atau model suara melalui speaker/headphone. Keyboard biasanya lebih ringan dan dapat memiliki tuts lebih sedikit; respons dinamika dan bobot tuts berbeda menurut model. MIDI controller mengirim pesan nada, velocity, dan kontrol ke perangkat lunak; tanpa sumber bunyi tersambung, ia tidak menghasilkan suara piano sendiri.',
'Pedal kanan atau sustain membiarkan resonansi berlanjut setelah tuts dilepas. Pedal kiri una corda mengubah warna/volume pada grand piano; mekanisme upright berbeda. Sostenuto pada grand menahan nada yang sedang berbunyi saat pedal ditekan. Pedal tengah upright sering merupakan peredam latihan, sehingga periksa instrumenmu. Jangan menganggap semua pedal tengah adalah sostenuto.',
'Cari jarak bangku yang memberi ruang siku dan menjangkau tuts tanpa membungkuk. Kaki bertumpu pada lantai atau penyangga. Coba beberapa tinggi bangku dan dengarkan apakah gerakan lebih mudah. Bahu, pergelangan, dan jari boleh menyesuaikan; ukuran tubuh berbeda. Mulai 2 menit, lepaskan tangan, lalu periksa napas dan ketegangan. Jika nyeri, hentikan latihan dan evaluasi penyebab bersama pengajar atau tenaga yang sesuai.'
],['Damper: peredam senar','Velocity: nilai kekuatan/kecepatan tekan MIDI, bukan ukuran ketegangan tubuh','Register: wilayah tinggi-rendah nada'], 'C4 (tahan 2 ketuk), diam 2 ketuk. Kanan jari 1 atau 2 yang nyaman. Ulangi tanpa lalu dengan sustain.', ['Identifikasi jenis instrumen dan sumber bunyinya.','Atur bangku, mainkan satu C dengan beberapa jari tanpa menekan keras.','Bandingkan pelepasan nada dengan sustain mati/aktif.'], 'Tulis perbedaan instrumenmu dengan piano akustik; buat refleksi/rekaman posisi dari samping.', 'Bahu terangkat atau badan menjangkau ke depan: atur jarak dan tinggi; lepaskan tangan di antara percobaan.',q('MIDI controller tanpa sumber bunyi tersambung…',['Tetap memiliki senar','Mengirim pesan; belum tentu berbunyi','Selalu memiliki pedal sostenuto'],1,'MIDI adalah data permainan. Suara harus dibuat perangkat yang menerima data.'),[60,null,60,null],[1,null,2,null]),
chapter('keys','Nama nada, oktaf, dan nomor jari','Menemukan nada yang diminta tanpa menghitung dari ujung keyboard.',old(1,0).concat('C4 adalah C tengah dalam penamaan ilmiah yang digunakan website (MIDI 60). Perangkat lain dapat menyebutnya C3 atau C5: cocokkan nomor MIDI dan bunyinya. Nama nada berulang setiap oktaf. Naik bergerak ke kanan dan terdengar lebih tinggi. Semiton adalah jarak ke tuts terdekat; satu nada penuh berisi dua semiton. E–F dan B–C adalah semiton walau keduanya putih.'),['Oktaf: interval delapan nama nada, 12 semiton','Semiton: jarak tuts terdekat','Jari 1–5: ibu jari sampai kelingking, sama di kedua tangan'], 'Kanan C4 D4 E4 F4 G4: 1 2 3 4 5\nKiri C3 D3 E3 F3 G3: 5 4 3 2 1. Naik lalu turun.', ['Cari C dengan dua tuts hitam, lalu F dengan tiga tuts hitam.','Cari D, A, dan B pada tiga oktaf; sebut sebelum menekan.','Mainkan C–G naik/turun, tangan terpisah, satu nada tiap ketuk.'], 'Minta orang lain menyebut enam nada acak di beberapa register; catat yang masih tertukar.', 'Menghafal letak C hanya satu oktaf: cari pola hitam pada wilayah baru sebelum menekan.',q('C4 dan C5 berbeda…',['Satu oktaf','Satu semiton','Hanya nomor jari'],0,'Keduanya bernama C; C5 berada 12 semiton di atas C4.'),[60,62,64,65,67,65,64,62,60],[1,2,3,4,5,4,3,2,1]),
chapter('pulse','Pulsa dan melodi pertama','Mempertahankan ketukan saat nada dan tangan berubah.',old(1,1).concat(old(1,2)),['Pulsa: ketukan dasar berulang','BPM: ketukan per menit','Ritme: susunan waktu bunyi dan diam'], '4/4: | C4(1) D4(1) E4(2) | G4(2) diam(2) |. Jari 1 2 3 5. Kiri satu oktaf bawah: 5 4 3 1.', ['Tepuk 8 pulsa pada 50–60 BPM atau lebih lambat bila perlu.','Mainkan contoh kanan, lalu kiri; hitung saat diam.','Matikan metronom 4 ketuk lalu nyalakan: periksa pulsa internal.'], 'Ciptakan pola lima nada 4 birama dengan satu istirahat; tulis durasinya dan rekam.', 'Mempercepat nada pendek: hitung subdivisi; metronom mengukur waktu, bukan kualitas keseluruhan.',q('Saat dua ketuk istirahat…',['Hitungan tetap berjalan','Tempo harus berhenti','Pedal harus ditahan'],0,'Diam tetap mengisi waktu dalam birama.'),[60,62,64,67,null],[1,2,3,5,null])]},
{id:'notation',number:2,title:'Membaca notasi dan ritme dasar',requires:['foundation'],legacy:2,criteria:'Baca melodi baru, tepuk ritme beristirahat, lalu mainkan dari partitur tanpa bergantung demonstrasi.',chapters:[
chapter('staff','Paranada, dua kunci, dan interval','Membaca grand staff dengan nada penanda.',old(2,0).concat('Grand staff menggabungkan paranada kunci G dan F dengan kurung. Umumnya kanan membaca wilayah atas dan kiri bawah, tetapi pembagian tangan mengikuti partitur, bukan hukum tetap. Baca bentuk: posisi berurutan berarti langkah; garis ke garis berikut berarti terts. Cari C4, G4, F3 dahulu, lalu ukur langkah dari penanda. Garis tambahan mengikuti urutan garis-ruang yang sama.'),['Paranada: lima garis tempat not','Grand staff: gabungan dua paranada','Garis tambahan: perluasan di luar lima garis'], 'Kunci G: C4 D4 E4 G4 E4 (1 2 3 5 3)\nKunci F: C3 E3 G3 E3 C3 (5 3 1 3 5).', ['Temukan tiga penanda pada gambar dan piano.','Baca arah serta interval sebelum nama nada.','Baca 2 birama setiap tangan lalu satu nada panjang kiri bersama melodi kanan.'], 'Buat kartu lima not berbeda untuk tiap kunci, acak urutannya, dan baca tanpa label huruf.', 'Menganggap kunci menentukan tangan selamanya: lihat register, tanda tangan, dan kenyamanan saat pembagian berubah.',q('Kunci F menandai…',['F3 pada garis keempat dari bawah','F4 pada garis kedua','Semua not dimainkan kanan'],0,'Dua titik kunci F mengapit garis F3.'),[60,62,64,67,64,48,52,55,52,48],[1,2,3,5,3,5,3,1,3,5]),
chapter('meter','Nilai not, birama, dan subdivisi','Membedakan tempo, tanda birama, dan panjang nada.',[
'Pada birama 2/4 ada dua ketukan seperempat, 3/4 tiga, dan 4/4 empat. Angka bawah menentukan unit nilai not; angka atas menyatakan jumlah unit dalam birama. Tempo menentukan kecepatan unit ketukan yang ditunjukkan: tanda seperempat = 60 berbeda dari setengah = 60. Tanda birama tidak menentukan cepat-lambat.',
'Not penuh bernilai empat seperempat, setengah dua, seperempat satu, dan seperdelapan setengah dalam contoh seperempat sebagai ketukan. Istirahat bernilai durasi yang sama dengan not pasangannya. Titik menambah setengah nilai awal: setengah bertitik = tiga seperempat; seperempat bertitik = satu setengah. Tie menggabungkan durasi dua nada dengan tinggi yang sama, termasuk melewati garis birama; nada kedua tidak dipukul lagi.',
'Hitung seperdelapan 1-dan-2-dan. Untuk pola bertitik, tempatkan nada berikut pada subdivisi yang benar, bukan menebak dari bunyi. Tepuk ritme dahulu sambil menghitung, lalu gunakan satu tuts. Di 3/4, pola 1+1+1 selesai satu birama; not setengah + seperempat juga selesai satu birama. Tiga birama berbeda dapat memiliki tempo seperempat yang sama.'
],['Birama: kelompok ketukan','Subdivisi: pembagian ketukan','Tie: ikatan durasi nada sejenis','Not bertitik: nilai awal ditambah setengah'], '3/4 | C4(2) D4(1) | E4(1) diam(1) G4(1) | C4(3) |. Jari 1 2 3 5 1.', ['Tepuk 2/4, 3/4, 4/4 pada 50 BPM.','Isi setiap birama dengan nilai yang jumlahnya benar.','Mainkan pola dengan istirahat dan hitung 1-dan sepanjang waktu.'], 'Tuliskan masing-masing dua birama 2/4, 3/4, dan 4/4; tepuk sebelum memainkan.', 'Menyamakan 3/4 dengan tempo cepat: bandingkan 3/4 dan 4/4 pada BPM sama.',q('Not seperempat bertitik dalam 4/4 bernilai…',['1½ ketuk','3 ketuk','½ ketuk'],0,'Titik menambah setengah dari satu ketuk: 1 + ½.'),[60,62,64,null,67,60],[1,2,3,null,5,1]),
chapter('symbols','Aksidental, artikulasi, dan membaca baru','Menerapkan simbol saat membaca frasa yang belum dihafal.',old(2,1).concat('Slur mengelompokkan nada berbeda menjadi satu gerak/frasa, umumnya legato; tie mengikat tinggi nada yang sama menjadi satu durasi. Staccato memperpendek bunyi tanpa mempercepat ketukan. Tanda ulang berupa dua titik dan garis ganda meminta bagian dimainkan kembali. Pada ending 1 dan 2, mainkan ending 1 putaran pertama, lalu lewati menuju ending 2 pada pengulangan. Sebelum membaca, pindai kunci, tanda mula, birama, ritme, titik ulang, dan posisi awal. Pilih materi baru yang lebih mudah dari karya utama.'),['Kres: naik satu semiton','Mol: turun satu semiton','Natural: membatalkan aksidental','Slur: pengelompokan/artikulasi frasa'], 'C4 D4 E♭4 F4 | G4 F4 E♭4 C4. Kanan 1 2 3 4 5 4 3 1; slur 4 nada pertama, staccato 4 berikut.', ['Baca aksidental dan masa berlakunya di birama.','Mainkan legato lalu staccato dengan pulsa sama.','Baca variasi not baru sebelum mendengar audio; gunakan kunci G dan F secara bertahap.'], 'Ubah dua nada pada contoh dan berikan kepada teman; baca versi teman dalam satu pengambilan.', 'Mendengar contoh berulang sebelum membaca: pisahkan karya belajar dari uji sight-reading baru.',q('Tie dan slur berbeda karena…',['Tie mengikat tinggi sama; slur mengelompokkan frasa','Slur menaikkan nada','Tie selalu dimainkan staccato'],0,'Tie menyambung durasi tanpa serangan ulang; slur memberi arah artikulasi/frasa.'),[60,62,63,65,67,65,63,60],[1,2,3,4,5,4,3,1])]},
{id:'coordination',number:3,title:'Koordinasi dua tangan',requires:['notation'],legacy:3,criteria:'Mainkan karya pendek dua tangan; melodi jelas, potongan sulit stabil, dan pulih tanpa kehilangan pulsa.',chapters:[
chapter('together','Gerak searah, berlawanan, dan titik temu','Menyatukan kedua tangan satu potongan setiap kali.',old(3,0).concat('Gerak paralel berarti kedua suara bergerak dengan arah sama; gerak berlawanan berarti satu naik saat yang lain turun. Latih kanan C4–G4 naik dan kiri C3–G3 naik untuk searah. Untuk berlawanan, kanan C4–G4 naik dan kiri C4–F3 turun. Penjarian berbeda menurut arah: jangan menyalin nomor kanan ke kiri. Pertemuan kedua tangan lebih mudah dipelajari lewat pola ketukan daripada menatap setiap jari.'),['Gerak paralel: arah suara sama','Gerak berlawanan: arah suara berlawanan','Potongan: unit latihan kecil'], 'Kanan C4 D4 E4 G4: 1 2 3 5\nKiri C3(4 ketuk): 5; lalu G2(4): 5. Tandai serangan bersamaan di ketuk 1.', ['Mainkan masing-masing tangan pada 40–60 BPM.','Mainkan hanya serangan yang bersamaan.','Gabungkan satu birama, tambah birama tetangga dengan overlap satu ketuk.'], 'Pilih dua birama sulit; bandingkan tiga pengulangan dengan penjarian tertulis yang sama.', 'Mengulang seluruh lagu saat macet: ambil satu ketuk sebelum dan sesudah titik macet.',q('Overlap saat menyambung potongan berarti…',['Ada bagian kecil yang ikut diulang pada dua potongan','Semua nada ditahan pedal','Tangan bermain secepat mungkin'],0,'Tumpang tindih kecil melatih sambungan, bukan hanya isi potongan.'),[[48,60],62,64,67,[43,65],64,62,60],['K5+R1',2,3,5,'K5+R4',3,2,1]),
chapter('accompaniment','Melodi, bass, blok, dan broken chord','Menjaga pengiring tetap stabil di bawah melodi.',old(3,1).concat('Akor blok memainkan beberapa nada bersamaan; broken chord memainkannya bergiliran. Latih kiri C3–E3–G3–E3 (5–3–1–3) setiap ketuk, sementara kanan menahan C5 empat ketuk. Lalu kanan C5–B4–A4–G4. Jangan menambah kompleksitas kedua tangan sekaligus. Bass akar satu nada dapat menjadi tahap antara sebelum blok atau akor pecah. Dengarkan keseimbangan dari rekaman, bukan dari rasa berat pada jari.'),['Akor blok: nada bersama','Broken chord: akor dipecah berurutan','Balance: perbandingan bunyi melodi dan pengiring'], 'Kiri C3 E3 G3 E3: 5 3 1 3\nKanan C5(4) lalu B4 A4 G4(2): 5 4 3 2.', ['Latih bass tunggal lalu akor blok.','Pecah akor kiri sementara kanan menahan nada panjang.','Tambahkan melodi bergerak hanya ketika iringan tidak terputus.'], 'Rekam dua versi: iringan keras dan lembut. Jelaskan di mana melodi lebih jelas.', 'Kiri menutupi kanan: sederhanakan pengiring dan kurangi velocity/volume kiri; jangan menaikkan semua bunyi.',q('Cara bertahap belajar broken chord dengan melodi…',['Iringan dulu, kanan nada panjang, baru melodi bergerak','Langsung banyak lompatan','Gunakan pedal terus'],0,'Mengubah satu tuntutan setiap langkah membantu menemukan sumber kesulitan.'),[[48,72],52,55,52,[48,71],52,[55,69],[52,67]],['K5+R5','K3','K1','K3','K5+R4','K3','K1+R3','K3+R2']),
chapter('independence','Artikulasi berbeda dan pemulihan kesalahan','Memainkan melodi legato dengan bass pendek tanpa kehilangan pulsa.',old(3,2).concat('Mulai kanan legato dan kiri nada pendek pada ketuk 1. Dengarkan kapan kiri dilepas tanpa memotong sambungan kanan. Bila artikulasi tertukar, latih pola satu tuts tiap tangan dahulu. Saat membaca utuh, jangan kembali ke awal setelah satu salah nada; lanjut ke ketuk atau titik jangkar berikutnya. Pada sesi perbaikan, hentikan dan ulang potongan dengan tujuan yang spesifik.'),['Artikulasi: cara memulai/menyambung/melepas bunyi','Titik jangkar: tempat mulai atau pulih yang dikenali'], 'Kanan C4 D4 E4 F4 (1 2 3 4), legato; kiri C3 pendek pada 1 (5), G2 pendek pada birama berikut (5).', ['Latih pelepasan kiri di bawah satu nada kanan panjang.','Tambahkan empat nada kanan tanpa mengubah kiri.','Simulasikan salah nada, teruskan pulsa ke awal birama berikut.'], 'Mainkan karya 8 birama satu pengambilan; catat jenis gangguan dan cara pulih.', 'Menahan napas ketika koordinasi meningkat: berhenti, lepaskan tangan, kecilkan potongan dan tempo.',q('Sesi bermain utuh dan perbaikan detail…',['Memiliki tujuan berbeda','Harus selalu berhenti tiap kesalahan','Tidak perlu rekaman'],0,'Sesi utuh melatih kesinambungan; sesi detail memecahkan masalah spesifik.'),[[48,60],62,64,65,[43,67],65,64,60],['K5+R1',2,3,4,'K5+R5',4,3,1])]},
{id:'technique',number:4,title:'Teknik dan tangga nada',requires:['coordination'],legacy:6,criteria:'Tangga nada/arpeggio sesuai cakupan terpilih, penjarian konsisten, bunyi rata, dan penerapan dalam karya.',chapters:[
chapter('scales','Mayor di semua tonalitas secara bertahap','Menghubungkan tanda mula, bunyi, dan pergantian posisi.',old(6,0).concat('Pola lima jari mayor adalah 2–2–1–2; minor 2–1–2–2. Mulai satu oktaf, kemudian dua, baru empat ketika perpindahan nyaman. Urutan belajar yang dapat dipilih: C G D A E B, lalu F B♭ E♭ A♭ D♭ G♭; F♯/G♭ mempunyai bunyi sama pada piano namun ejaan berbeda. Tabel penjarian lengkap ada di bawah. Latih tangan terpisah dahulu; searah dan berlawanan memakai titik temu berbeda. Tempo awal seperempat = 40–60, satu nada per ketuk; kemudian dua nada per ketuk. Tambah sekitar 4 BPM setelah tiga pengulangan bersih. Ini panduan, bukan batas kemampuan universal.'),['Tonalitas: pusat nada dan hubungan nada','Tanda mula: kres/mol yang berlaku pada bagian','Thumb passage: perpindahan posisi sekitar ibu jari'], 'C mayor naik R 1 2 3 1 2 3 4 5; L 5 4 3 2 1 3 2 1. Untuk dua oktaf R sambung 4→1 sebelum C berikut; akhiri 5 hanya pada puncak akhir.', ['Mainkan pola lima jari mayor/minor dan dengarkan terts.','Pelajari satu tonalitas per sesi menggunakan tabel.','Variasikan panjang–pendek, pendek–panjang, p/mf dan legato/staccato; kembalikan ritme rata.'], 'Pilih 3 tonalitas dekat karya; tulis nada dan penjarian, rekam rata tanpa aksen ibu jari.', 'Aksen keras saat ibu jari: kecilkan gerak, siapkan perpindahan seluruh tangan, dan turunkan tempo.',q('Empat oktaf sebaiknya dimulai…',['Setelah perpindahan lebih pendek nyaman','Saat BPM paling tinggi','Tanpa memperhatikan bunyi'],0,'Cakupan diperluas berdasarkan kontrol dan kebutuhan karya, bukan angka kecepatan.'),[60,62,64,65,67,69,71,72],[1,2,3,1,2,3,4,5]),
chapter('minor','Minor, kromatis, triad, dan arpeggio','Membedakan bentuk minor serta melatih pola akor.',old(6,1).concat('Minor natural A: A B C D E F G A. Harmonis menaikkan tingkat 7 menjadi G♯. Minor melodis dalam latihan klasik naik A B C D E F♯ G♯ A, turun dengan natural; dalam jazz, bentuk naik sering dipakai kedua arah. Kromatis memakai setiap semiton. Usulan kanan: ibu jari pada putih, jari 3 pada hitam, jari 2 untuk putih berurutan E–F dan B–C, dengan akhir menyesuaikan arah. Triad C = C E G; inversi E G C dan G C E. C arpeggio satu oktaf R 1–2–3–5, L 5–3–2–1; sambungan multioktaf memerlukan pergantian posisi yang direncanakan. Dominan tujuh C7 = C E G B♭; diminished seventh B–D–F–A♭ (0–3–6–9). Pecah akor bila rentang tidak nyaman.'),['Minor harmonis: tingkat 7 dinaikkan','Arpeggio: nada akor berurutan melintasi register','Diminished seventh: tumpukan terts minor'], 'A minor melodis naik A3 B3 C4 D4 E4 F♯4 G♯4 A4: R 1 2 3 1 2 3 4 5. Turun A4 G4 F4 E4 D4 C4 B3 A3: 5 4 3 2 1 3 2 1.', ['Bandingkan tiga minor dengan akar sama.','Mainkan kromatis satu oktaf lambat, sebut semiton.','Mainkan triad/inversi lalu arpeggio; coba C7 dan Bdim7 dengan posisi dekat.'], 'Pilih minor relatif dari tonalitas karya; mainkan ketiga bentuk dan jelaskan beda penggunaannya.', 'Menggunakan satu penjarian untuk semua akar: periksa posisi hitam/putih dan rencanakan sambungan.',q('Minor melodis klasik turun biasanya…',['Kembali ke minor natural','Tetap selalu bentuk naik','Menjadi mayor'],0,'Konvensi latihan klasik menurunkan kembali tingkat 6 dan 7; praktik jazz dapat berbeda.'),[57,59,60,62,64,66,68,69,67,65,64,62,60,59,57],[1,2,3,1,2,3,4,5,4,3,2,1,3,2,1]),
chapter('movement','Lompatan, repetisi, oktaf, dan double notes','Memilih gerakan yang memecahkan kebutuhan musikal.',[
'Lompatan dimulai dengan memetakan tujuan. Sentuh tuts awal dan tujuan tanpa bunyi, kemudian mainkan pelan. Biarkan mata mendahului gerak; lepaskan tuts awal sebelum berpindah ketika artikulasi memungkinkan. Jangan merentangkan jari sepanjang lompatan. Latih kedatangan senyap, lalu bunyi pada ketukan yang benar.',
'Repetisi satu nada dapat memakai pergantian jari 3–2–1 bila sesuai instrumen dan tempo, atau jari yang sama dengan pelepasan efisien pada tempo lambat. Respons mekanisme tuts memengaruhi hasil. Oktaf dan double notes memerlukan jangkauan, koordinasi pelepasan, dan kontrol dua suara. Mulai interval kecil seperti terts C–E ke D–F, R 1–3 lalu 2–4; jangan memaksa rentang oktaf. Jika belum nyaman, pecah atau ubah susunan.',
'Pilih teknik dari masalah karya: tangga nada untuk frasa bertangga, arpeggio untuk akor pecah, latihan kedatangan untuk lompatan. Satu buku latihan bukan satu-satunya jalan. Latih 20–30 detik, istirahat, dengarkan, kemudian kembali ke frasa utuh. Untuk oktaf cepat, repetisi panjang, dan double notes lanjut, pengajar perlu mengamati gerak individu; contoh website adalah persiapan, bukan resep universal.'
],['Double notes: dua nada bergerak bersama','Repetisi: pengulangan nada','Efisiensi: gerak secukupnya untuk hasil bunyi'], 'C4→C5: R 1→5 hanya bila nyaman, dapat 2→2 dengan perpindahan. Terts C4+E4→D4+F4→E4+G4: 1+3, 2+4, 3+5.', ['Petakan tujuan lompatan tanpa bunyi pada 40 BPM.','Mainkan repetisi 4 nada dengan jeda; bandingkan jari sama dan berganti.','Mainkan terts pelan, dengarkan kedua nada serempak, lalu terapkan satu frasa.'], 'Pilih satu masalah nyata, buat latihan dua ketuk, lalu bandingkan frasa sebelum/sesudah.', 'Mengejar oktaf cepat meski tegang: hentikan, kurangi rentang/durasi dan minta pengamatan pengajar.',q('Latihan teknik dipilih terutama berdasarkan…',['Masalah musikal dan kebutuhan individu','Kecepatan orang lain','Jumlah halaman buku'],0,'Teknik berguna ketika memperbaiki bunyi dan gerakan dalam musik yang dimainkan.'),[[60,64],[62,65],[64,67],null,60,72,60,72],['1+3','2+4','3+5',null,1,5,1,5])]},
{id:'harmony',number:5,title:'Harmoni dan pengiring',requires:['technique'],legacy:4,criteria:'Iringi lead sheet, pindahkan progresi ke beberapa tonalitas, gunakan inversi, dan jelaskan fungsi akor.',chapters:[
chapter('chords','Interval, triad, akor tujuh, sus, dan add','Membentuk akor dari nama dan intervalnya.',old(4,0).concat('Interval melodis dimainkan berurutan; harmonis bersama. Triad diminished = 0–3–6 (B D F), augmented = 0–4–8 (C E G♯). Major seventh 0–4–7–11 (Cmaj7), dominant seventh 0–4–7–10 (C7), minor seventh 0–3–7–10 (Cm7), half-diminished 0–3–6–10 (Bm7♭5). Sus2 mengganti terts dengan sekon; sus4 dengan kuart. Add9 menambah nada ke-9 tanpa otomatis memasukkan ketujuh; C9 umumnya dominant seventh plus D, sedangkan Cadd9 = C E G D. Extensions 9/11/13 memperluas susunan dan tidak harus dimainkan semuanya sekaligus. Gunakan nada penentu kualitas dan hindari rentang yang dipaksakan.'),['Akar: nada dasar pembentuk akor','Terts: interval tingkat ketiga','Extension: perluasan di atas ketujuh'], 'C Cminor Cdim Caug: C-E-G; C-E♭-G; C-E♭-G♭; C-E-G♯. R 1-3-5 sebagai awal, susun ulang bila perlu.', ['Dengarkan interval melodis lalu harmonis.','Ubah satu nada untuk membandingkan empat kualitas triad.','Tambahkan ketujuh, lalu bedakan C7, Cmaj7, Cadd9, C9.'], 'Bangun delapan simbol akor dari akar berbeda; sebut ejaan nada sebelum menekan.', 'Menganggap add9 wajib ketujuh: baca simbol dan periksa susunannya.',q('Cadd9 berbeda dari C9 karena…',['Add9 tidak otomatis menyertakan ketujuh','Add9 hanya nada D','C9 adalah C minor'],0,'C9 biasanya C E G B♭ D; Cadd9 C E G D.'),[[60,64,67],[60,63,67],[60,63,66],[60,64,68],[60,64,67,70],[60,64,67,71]],['1-3-5','1-3-5','1-3-5','1-3-5','1-2-3-5','1-2-3-5']),
chapter('function','Fungsi, kadens, inversi, dan voice leading','Mendengar arah harmoni serta menyusun perpindahan dekat.',old(4,1).concat('Dalam mayor, triad diatonik I ii iii IV V vi vii°. Tonika I memberi pusat; subdominan IV dan predominant ii menyiapkan gerak; dominan V atau V7 mengarah ke I. Kadens autentik V–I memberi penyelesaian; autentik sempurna memerlukan posisi dasar keduanya dan tonika di soprano akhir. Plagal IV–I, setengah berakhir V, deceptive sering V–vi. Fungsi harus didengar dalam konteks, bukan ditebak dari satu akor. Mainkan frase C–F–G–C, lalu ubah akhir ke Am dan bandingkan. Inversi memungkinkan suara bersama bertahan dan suara lain bergerak langkah kecil.'),['Angka Romawi: derajat/fungsi akor','Kadens: pengakhiran frasa harmonis','Voice leading: gerakan masing-masing suara'], 'I–IV–V–I C: R C E G→C F A→B D G→C E G; L C→F→G→C. Penjarian R awal 1-3-5, lalu 1-3-5/1-2-5 menurut posisi nyaman.', ['Sebut fungsi sambil memainkan I–IV–V–I.','Bandingkan empat kadens dengan melodi pendek.','Pertahankan nada bersama dan tulis gerak tiap suara.'], 'Analisis akhir dua frasa karya orisinal; jelaskan alasan terasa selesai atau menggantung.', 'Mengira setiap V–I autentik sempurna: periksa inversi dan soprano, bukan hanya nama akar.',q('Kadens setengah berakhir pada…',['V','Selalu I','Selalu vi'],0,'Akhir dominan menciptakan rasa belum selesai; akor sebelumnya dapat berbeda.'),[[48,60,64,67],[53,60,65,69],[55,59,62,67],[48,60,64,67]],['L5 R1-3-5','L5 R1-3-5','L5 R1-2-5','L5 R1-3-5']),
chapter('lead','Lead sheet, pola iringan, dan transposisi','Mengiringi melodi dengan pola yang sesuai ruang dan birama.',old(4,2).concat('Lead sheet menampilkan melodi, simbol akor, dan bentuk. Chord chart dapat hanya menampilkan akor/bagian tanpa melodi. Di 3/4 coba bass ketuk 1 dan akor 2–3; di 4/4 coba bass 1 dan akor 2/4. Alberti bass menyusun rendah–tinggi–tengah–tinggi, misalnya C3 G3 E3 G3 (5–1–3–1), lazim dalam gaya Klasik. Transposisi melodi mempertahankan interval: C D E menjadi G A B di G; progresi ikut berpindah menurut derajat. Periksa nada tertinggi/terendah untuk penyanyi, lalu pilih register dan iringan yang tidak menutupi vokal. Melodi dapat memakai chord tones pada titik stabil dan passing tones di antaranya.'),['Lead sheet: melodi dengan simbol akor','Alberti bass: rendah–tinggi–tengah–tinggi','Chord tone: nada anggota akor'], 'Melodi C4 D4 E4 G4 | A4 G4 E4 D4. Akor C | F. R 1 2 3 5 lalu 5 4 2 1; L blok C3 E3 G3 = 5 3 1.', ['Baca melodi dan simbol terpisah sebelum gabungan.','Coba blok, broken chord, Alberti, dan pola pop pada tempo tetap.','Transposisikan melodi serta I–V–vi–IV dari C ke G lalu F.'], 'Buat lead sheet 8 birama dan rekam dua pola; pilih pola yang mendukung arah melodi.', 'Mengganti akor terlambat saat pola rumit: sederhanakan menjadi bass/akor panjang dahulu.',q('Alberti bass memakai urutan…',['Rendah–tinggi–tengah–tinggi','Semua nada bersamaan','Selalu naik kromatis'],0,'Pola C–G–E–G mengisi harmoni sambil memberi gerak iringan.'),[48,55,52,55,53,60,57,60],[5,1,3,1,5,1,3,1])]},
{id:'musicality',number:6,title:'Musikalitas, sentuhan, dan pedal',requires:['harmony'],legacy:5,criteria:'Karya dengan frase/dinamika terencana, melodi jelas, pedal bersih, dan jurnal alasan interpretasi.',chapters:[
chapter('phrases','Dinamika, frase, artikulasi, dan voicing','Membentuk beberapa lapisan suara yang dapat didengar.',old(5,0).concat('Voicing berarti memilih suara yang ditonjolkan dalam tekstur, termasuk nada teratas akor, suara dalam, atau bass. Nyanyikan masing-masing garis dan mainkan sendiri dahulu. Di akor C E G, coba G lebih menonjol, kemudian E, tanpa mengubah semua volume. Staccato mempunyai banyak panjang bunyi menurut gaya, tempo, dan ruangan. Legato jari menggunakan peralihan tuts yang menghubungkan bunyi; jangan menahan semua jari lama-lama. Frase harus mempunyai arah yang didengar, bukan sekadar simbol tertulis.'),['Voicing: penonjolan suara tertentu','Diminuendo: bunyi berangsur lembut','Frase: unit kalimat musikal'], 'C4 D4 E4 G4 | A4 G4 E4 C4, R 1 2 3 5 5 4 2 1. Velocity 40→55→70→90→105→80→60→40 sebagai contoh hubungan dinamika.', ['Nyanyikan arah frase lalu tandai satu puncak.','Mainkan p, mf, f tanpa menegang.','Mainkan akor sambil menonjolkan nada atas, lalu suara dalam.'], 'Rekam satu karya dengan rencana frase; minta pendengar menyebut puncak yang mereka dengar.', 'Setiap nada sama keras: rencanakan arah dan dengarkan rekaman; perubahan tekanan tidak otomatis frase.',q('Voicing dapat menonjolkan…',['Melodi, suara dalam, atau bass menurut konteks','Hanya nada paling tinggi selamanya','Semua nada sama keras'],0,'Tujuannya membuat hubungan lapisan musik dapat didengar.'),[60,62,64,67,69,67,64,60],[1,2,3,5,5,4,2,1]),
chapter('pedal','Pedal langsung, sinkop, dan kejernihan','Memilih pergantian pedal dengan telinga.',old(5,1).concat('Pedal langsung turun bersamaan serangan dan dapat memberi aksen resonansi. Pedal sinkop turun setelah serangan; pada perubahan harmoni, akor baru berbunyi, pedal lama dilepas lalu ditekan kembali sehingga tidak ada jeda panjang. Jangan menunggu seluruh bunyi hilang sebelum menginjak lagi. Una corda memberi warna berbeda; sostenuto menahan nada yang sudah aktif saat ditekan dan membiarkan nada berikutnya terlepas normal. Half-pedal mengatur seberapa jauh damper lepas; instrumen harus mendukung pedal kontinu. Simulasi sustain website hanya on/off dan tidak menguji gerak kaki atau half-pedal. Latih asli di register bass dan atas karena resonansi berbeda.'),['Syncopated pedal: pergantian setelah serangan baru','Half-pedal: posisi pedal sebagian','Una corda: perubahan warna oleh pedal kiri'], 'C3+E3+G3 (L5-3-1) → F3+A3+C4 (L5-3-1), tahan 4 ketuk tiap akor. Dengarkan tanpa pedal, pedal langsung, lalu sinkop.', ['Dengar akor terpisah tanpa pedal.','Latih angkat-tekan setelah akor baru pada tempo lambat.','Ubah saat harmoni keruh; kurangi durasi atau kedalaman bila instrumen mendukung.'], 'Rekam 8 birama tanpa/dengan pedal dan tandai lokasi yang masih mengaburkan harmoni.', 'Pedal menutupi nada salah: perbaiki nada/artikulasi tanpa pedal sebelum menambah resonansi.',q('Half-pedal di website ini…',['Belum disimulasikan; perlu instrumen yang mendukung','Otomatis diukur dari MIDI on/off','Sama dengan menahan semua tuts'],0,'Sustain on/off tidak memberi posisi kontinu atau evaluasi gerak kaki.'),[[48,52,55],[53,57,60],[55,59,62],[48,52,55]],['5-3-1','5-3-1','5-3-1','5-3-1']),
chapter('interpretation','Rubato dan keputusan interpretasi','Menjelaskan pilihan tempo dan ekspresi dari struktur musik.',old(5,2).concat('Bandingkan dua versi dengan tempo dasar sama: satu stabil dan satu melebar menjelang kadens. Jangan memberi rubato yang sama pada setiap birama; cari fungsi frasa dan harmoni. Dengarkan apakah bagian utama masih terasa menuju tujuan dan apakah pemain lain bisa mengikuti. Dalam ensemble, sepakati titik keluwesan serta isyarat napas. Catat alasan: misalnya dominan ditahan sedikit untuk menonjolkan tegangan, kemudian tonika diselesaikan. Evaluasi bukan hanya menyukai versi yang lebih lambat.'),['Rubato: keluwesan waktu terencana','Interpretasi: keputusan musikal berdasarkan struktur/gaya'], 'C4 E4 G4 E4 | D4 F4 G4 C4. R 1 2 4 2 | 1 3 4 1; versi kedua sedikit melebar pada G terakhir sebelum C.', ['Mainkan stabil dengan metronom.','Tentukan satu titik rubato dan jelaskan alasannya.','Bandingkan dua rekaman utuh; dengarkan kesinambungan serta puncak.'], 'Tulis tiga keputusan interpretasi dan satu kemungkinan alternatif; uji lewat rekaman.', 'Menyebut jeda karena lupa sebagai rubato: perbaiki koordinasi/memori dahulu.',q('Rubato yang mendukung musik…',['Memiliki arah frasa dan struktur','Menghapus kebutuhan memahami pulsa','Menutupi bagian belum lancar'],0,'Keluwesan waktu merupakan keputusan sadar di atas pemahaman pulsa.'),[60,64,67,64,62,65,67,60],[1,2,4,2,1,3,4,1])]},
{id:'listening',number:7,title:'Telinga, sight-reading, dan memori',requires:['musicality'],legacy:8,criteria:'Baca materi baru, tirukan pola, mulai dari beberapa titik, dan identifikasi harmoni/bentuk karya.',chapters:[
chapter('ear','Interval, akor, kadens, dan meniru','Menghubungkan yang terdengar dengan nada yang dimainkan.',[
'Nyanyikan nada awal yang nyaman, lalu nada tujuan. Bandingkan sekon langkah C–D, terts C–E, kuart C–F, kuint C–G, dan oktaf C–C. Nama interval memuat hitungan huruf serta kualitas: C–E mayor, C–E♭ minor. Dengarkan melodis naik/turun dan harmonis; jangan bergantung satu lagu pengingat saja. Pindahkan akar agar telinga mengenali hubungan, bukan tinggi absolut.',
'Bandingkan triad mayor/minor/diminished/augmented dengan akar sama, kemudian akar berbeda. Dengarkan terts dan kuint. Kadens perlu konteks: mainkan I–IV–V–I, I–IV–V, lalu I–IV–V–vi; nyanyikan bass dan dengarkan rasa selesai/menggantung. Studio saat ini menguji mayor/minor; kualitas lain dan kadens dilatih memakai contoh serta instrumen.',
'Untuk meniru, dengar pola 3–5 nada sekali tanpa melihat tuts, nyanyikan, lalu cari nada awal dan arah. Pecah ritme dari tinggi nada: tepuk dahulu, kemudian satu tuts, baru melodinya. Dalam menemukan melodi, cari pusat nada dan titik istirahat; uji kandidat, dengarkan, revisi. Rekam proses dan catat strategi yang berhasil, bukan hanya jumlah jawaban benar.'
],['Aural: melalui pendengaran','Dictation: mencatat musik dari bunyi','Kontur: arah tinggi-rendah melodi'], 'C4 E4 D4 G4 C4 (R 1 3 2 5 1); dengar tanpa melihat sebelum memainkan. Kadens C–F–G–C.', ['Nyanyikan tiga interval dengan akar berbeda.','Bandingkan mayor/minor di studio, lalu empat triad di piano.','Tiru pola 3 nada, naik ke 5, kemudian sertakan istirahat.'], 'Minta orang lain memainkan pola baru dan satu kadens; sebut kontur, ritme, lalu cari nadanya.', 'Menghafal tombol jawaban dari contoh berulang: acak akar dan arah, gunakan pola baru.',q('Melatih interval dengan beberapa akar membantu…',['Mengenali hubungan bunyi, bukan satu tinggi absolut','Mengubah nilai not','Menghilangkan perlu mendengar'],0,'Hubungan interval tetap meskipun seluruh pola ditransposisikan.'),[60,64,62,67,60],[1,3,2,5,1]),
chapter('sight','Membaca baru dan transposisi','Memindai partitur lalu menjaga aliran dalam satu percobaan.',old(2,2).concat('Gunakan 30–60 detik sebelum bermain untuk memindai tanda mula, birama, pola ritme, jangkauan, bentuk, dan bagian tersulit. Tentukan tempo dari bagian tersulit itu. Lihat satu ketukan ke depan, baca interval serta blok harmoni. Kalau salah, lanjutkan pada pulsa berikutnya; perbaiki setelah percobaan utuh. Transposisi awal: frasa lima nada C–D–E–G ke G–A–B–D sambil mempertahankan durasi. Pisahkan latihan membaca tanpa audio dari sesi mempelajari karya. Generator variasi di halaman ini menyediakan motif baru; kerumitannya sengaja di bawah proyek repertoar.'),['Sight-reading: membaca musik baru saat memainkan','Scan: memindai sebelum bermain','Transposisi: memindahkan pusat nada'], '4/4 | C4 E4 D4(2) | F4 E4 D4 C4 |. R 1 3 2 | 4 3 2 1. Transposisi G4 B4 A4(2) | C5 B4 A4 G4.', ['Pindai contoh baru tanpa memutarnya.','Tepuk ritme lalu baca satu pengambilan utuh.','Pindahkan motif ke G/F dan baca dengan penjarian terencana.'], 'Baca tiga variasi berbeda dalam tiga hari, catat tempo nyaman dan tempat aliran terganggu.', 'Tempo dipilih dari birama paling mudah: turunkan berdasarkan bagian paling sulit.',q('Jika pola sudah dihafal, membacanya lagi…',['Menjadi latihan repertoar; perlu pola baru untuk sight-reading','Tetap menguji membaca baru','Membuktikan semua tingkat membaca'],0,'Uji membaca memerlukan materi yang belum pernah dipelajari.'),[60,64,62,65,64,62,60],[1,3,2,4,3,2,1]),
chapter('memory','Empat jalur memori dan titik jangkar','Memulai karya dari beberapa lokasi tanpa ketergantungan gerak.',old(8,1).concat('Memori visual mengingat letak partitur; auditori mengingat bunyi; motorik mengingat urutan gerak; analitis mengingat harmoni, bentuk, dan hubungan motif. Uji tiap jalur: nyanyikan tanpa bermain, sebut akor tiap bagian, bayangkan awal frasa, lalu mulai dari titik acak. Bila hanya bisa dari awal, pilih awal bagian B dan kadens sebagai jangkar. Latih awal tersebut setelah istirahat singkat, tidak selalu setelah memainkan bagian sebelumnya.'),['Memori analitis: ingatan struktur/harmoni','Jangkar: awal bagian yang dapat dipanggil mandiri'], 'Jangkar A: C4 E4 G4 (1 3 5); B: F4 A4 C5 (1 3 5); kadens: G4 B4 D5→C5 (1 3 5→4).', ['Nyanyikan satu frasa dari ingatan.','Sebut bentuk dan bass tanpa piano.','Mulai dari awal A, B, kadens, dan pertengahan frasa secara acak.'], 'Buat peta karya satu halaman; rekam tiga awal acak tanpa memainkan awalan.', 'Hafal cepat tetapi runtuh setelah salah: gunakan harmoni/pendengaran dan titik jangkar, bukan hanya pengulangan jari.',q('Memori yang paling tahan gangguan memakai…',['Bunyi, visual, gerak, dan analisis bersama','Gerakan jari saja','Kecepatan tinggi saja'],0,'Beberapa jalur saling membantu ketika satu jalur terganggu.'),[[60,64,67],[65,69,72],[67,71,74],[60,64,67]],['1-3-5','1-3-5','1-3-5','1-3-5'])]},
{id:'practice',number:8,title:'Repertoar dan strategi latihan menengah',requires:['listening'],legacy:8,criteria:'Beberapa karya utuh berbeda karakter, rencana masalah nyata, bukti sebelum/sesudah, dan program pendek dengan pemulihan.',chapters:[
chapter('diagnose','Memilih karya dan mendiagnosis masalah','Membuat rencana latihan dari analisis karya.',[
'Pilih karya yang sebagian besar tuntutannya sudah dikenali, dengan satu-dua tantangan baru yang terukur. Baca tanda mula, meter, rentang, tekstur, dan panjang. Coba birama tersulit pada tempo lambat sebelum memutuskan. Bedakan materi sight-reading yang lebih mudah, étude mini yang memusatkan satu teknik, dan karya utuh yang dipelajari sampai interpretasi.',
'Petakan bentuk A–B–A atau frasa tanya-jawab, tandai kadens dan perubahan tekstur. Diagnosis salah nada: periksa ejaan dan posisi; salah ritme: tepuk/hitung; gerak tidak nyaman: periksa penjarian/perpindahan dengan pengajar; interpretasi datar: nyanyikan dan rencanakan arah. Jangan memberi solusi sama berupa mengulang dari awal pada keempat masalah.',
'Tulis target sebagai hasil yang bisa diamati: dua birama perpindahan G–C tanpa jeda pada tempo nyaman, bukan latihan lagu 30 menit. Catat metode, percobaan, hasil, dan langkah berikut. Rekam sebelum latihan lalu setelahnya dengan tempo dan potongan yang sama sehingga perbandingan adil. Satu sesi berhasil belum menjamin konsistensi; uji lagi pada hari berbeda.'
],['Repertoar: kumpulan karya yang dipelajari/dipelihara','Diagnosis: menentukan sumber masalah','Etude: studi dengan fokus teknik musikal'], 'A: C E G E | D F G D; B: A C E C | F A G E. R gunakan 1-2-4-2 lalu 1-3-4-1; susun kembali untuk B.', ['Pindai rentang/bentuk dan uji bagian sulit.','Klasifikasikan satu gangguan: nada, ritme, gerak, atau interpretasi.','Buat target dua birama dan bandingkan rekaman.'], 'Pilih tiga karya dengan karakter berbeda; jelaskan satu tujuan teknik dan musikal masing-masing.', 'Karya jauh terlalu sulit menghabiskan seluruh sesi: pilih jembatan lebih sederhana dan konsultasikan rentang.',q('Target latihan yang dapat diamati adalah…',['Dua birama G–C tanpa jeda pada tempo nyaman','Bermain lebih bagus','Mengulang selama mungkin'],0,'Target konkret membuat metode dan hasil dapat dibandingkan.'),[60,64,67,64,62,65,67,62],[1,2,4,2,1,3,4,1]),
chapter('methods','Potongan, overlap, backward chaining, dan ritme','Memilih metode perbaikan lalu kembali ke bentuk asli.',[
'Potongan dapat satu ketuk, satu birama, atau frasa sesuai masalah. Mulai sedikit sebelum kesalahan agar gerak masuk ikut dilatih. Overlap menyambung potongan dengan satu-dua ketuk yang sama. Backward chaining mulai dari akhir frasa, tambah bagian sebelumnya, sehingga tujuan dan akhir menjadi semakin dikenal; ini bukan memainkan nada terbalik.',
'Tangan terpisah berguna ketika salah satu garis belum dipahami, tetapi gabungan tetap perlu dilatih untuk waktu pertemuan. Untuk alur nada rata, coba panjang–pendek dan pendek–panjang sambil menjaga kenyamanan; lalu kembali ke nilai not asli. Jangan menerapkan perubahan ritme pada semua karya tanpa mempertimbangkan artikulasi atau struktur.',
'Mulai pada tempo yang memberi kesempatan mengamati gerakan dan bunyi. Setelah tiga pengulangan stabil, naik sekitar 3–5 BPM; bila kualitas turun, kembali. Angka adalah alat merencanakan, bukan ukuran kepiawaian. Selingi potongan sulit dengan frasa utuh dan musik yang disukai. Bila metode tidak memperbaiki setelah beberapa percobaan, ubah diagnosis atau cari umpan balik.'
],['Backward chaining: membangun dari bagian akhir','Overlap: sambungan dengan bagian tumpang tindih','Variasi ritme: mengubah sementara distribusi durasi'], 'C D E F | G F E D | C(4). Mulai E D C, tambah G F E D C; nada tetap urutan aslinya. R 1 2 3 4 5 4 3 2 1.', ['Latih ketuk sebelum/sesudah gangguan.','Sambungkan dengan overlap, lalu bangun akhir frasa ke belakang.','Coba dua variasi ritme lalu kembalikan asli pada tempo sama.'], 'Catat metode yang membantu satu masalah dan metode yang tidak membantu; buktikan lewat rekaman.', 'Variasi menjadi kebiasaan baru: selalu akhiri sesi dengan ritme/artikulasi asli.',q('Backward chaining berarti…',['Belajar akhir dahulu lalu menambah bagian sebelumnya','Membalik semua nada','Bermain tanpa berhenti selamanya'],0,'Urutan musik tetap asli; bagian yang dipelajari diperluas dari akhir.'),[60,62,64,65,67,65,64,62,60],[1,2,3,4,5,4,3,2,1]),
chapter('program','Jadwal, pemeliharaan, rekaman, dan tampil','Menyiapkan program pendek yang konsisten.',old(8,0).concat('Susun minggu dengan satu karya utama, satu karya ringan/baca baru, dan satu karya lama. Rotasi karya lama agar tidak hanya satu lagu bertahan. Target dapat jumlah sesi dan menit, tetapi evaluasi utamanya perubahan kualitas. Untuk program singkat, susun pembuka, kontras, penutup; coba transisi dan hitungan sebelum mulai. Rekam satu pengambilan dengan kondisi realistis. Setelahnya, catat tempat pulih, arah frase, dan satu perbaikan untuk minggu depan. Kelulusan memerlukan beberapa karya utuh, bukan mengulang cuplikan audio demo.'),['Program: urutan karya untuk penampilan','Pemeliharaan: mengulang karya lama dengan tujuan','Refleksi: menilai bukti dan memilih langkah berikut'], 'Pembuka C mayor; kontras A minor; penutup C dengan kadens V–I. Gunakan penjarian tertulis pada setiap titik perpindahan, bukan improvisasi jari acak.', ['Susun jadwal tiga sesi dengan target berbeda.','Mainkan karya lama lalu bagian sulit karya baru.','Rekam program utuh, jeda antarkarya, dan latih pemulihan.'], 'Siapkan tiga karya berbeda karakter; kumpulkan rekaman sebelum/sesudah dan refleksi mingguan.', 'Mengukur sukses hanya menit: jelaskan perubahan nyata pada satu aspek rubrik.',q('Bukti kemajuan yang lebih kuat adalah…',['Rekaman sebanding sebelum/sesudah dan refleksi','Jumlah menit saja','Satu tombol selesai'],0,'Durasi membantu konsistensi kebiasaan; bukti permainan menunjukkan perubahan kompetensi.'),[60,64,67,72,57,60,64,69,[55,59,62],[48,60,64,67]],[1,2,3,5,1,2,3,5,'L5-3-1','L5 R1-3-5'])]},
{id:'classical',title:'Jalur klasik',requires:['practice'],legacy:7,criteria:'Program beberapa gaya, analisis bentuk, suara seimbang, keputusan sesuai partitur, serta umpan balik pengajar.',human:true,chapters:[
chapter('styles','Barok, Klasik, Romantik, dan kontemporer','Membedakan pilihan artikulasi, warna, dan bentuk dalam konteks gaya.',[
'Gaya Barok sering menonjolkan garis kontrapung dan gerak ritmis; artikulasi membantu motif terdengar. Gaya Klasik sering memakai frasa seimbang, kontras tema, dan harmoni yang jelas. Romantik sering memperluas warna, register, dan keluwesan frasa. Modern/kontemporer sangat beragam: tekstur, ritme, pedal, dan notasi harus dibaca dari karya. Ciri ini titik awal, bukan aturan semua komposer.',
'Bentuk biner A–B mempunyai dua bagian; ternary A–B–A kembali ke A; rondo mengulang refrain di antara episode, misalnya A–B–A–C–A. Variasi mengubah tema sambil menjaga hubungan tertentu. Pengantar sonata: eksposisi memperkenalkan tema/tonalitas, pengembangan mengolahnya, rekapitulasi mengembalikan materi dengan penyelesaian tonal; banyak karya memodifikasi kerangka ini.',
'Pilih invention untuk dua suara, sonatina sebagai jembatan bentuk/tekstur Klasik, lalu sonata sesuai tingkat; prelude, nocturne, dan étude dapat berkisar mudah hingga sangat lanjut. Judul genre tidak menjamin tingkat. Bandingkan edisi dan petunjuk partitur; pilih penjarian, pedal, artikulasi, dan tempo yang mendukung struktur, bukan menyalin satu rekaman.'
],['Polifoni: beberapa garis mandiri','Rondo: refrain bergantian episode','Eksposisi: pengenalan tema dalam sonata'], 'A C4 D4 E4 G4; B A4 G4 F4 E4; A kembali. R A 1-2-3-5; B 5-4-3-2. Bentuk A–B–A.', ['Mainkan motif dengan artikulasi terpisah lalu legato dan bandingkan.','Petakan A/B/kadens pada miniatur orisinal.','Jelaskan pilihan pedal/tempo dengan bukti struktur.'], 'Bandingkan dua karya berlisensi yang gaya/teksturnya berbeda; pilih dengan pengajar.', 'Menganggap semua Barok tanpa pedal atau semua Romantik rubato besar: uji kejernihan dan konteks partitur.',q('Bentuk ternary biasanya…',['A–B–A','A–B saja','Tema tanpa bagian'],0,'Kembalinya A membedakannya dari bentuk biner dasar.'),[60,62,64,67,69,67,65,64,60,62,64,60],[1,2,3,5,5,4,3,2,1,2,3,1]),
chapter('polyphony','Dua suara, ornamentasi, dan analisis','Mengendalikan garis mandiri dan hiasan dalam gaya.',legacy[6].lessons[0].body.concat('Latih suara atas dan bawah sambil menyanyikan suara lain; lalu mainkan keduanya dan ganti suara yang ditonjolkan. Untuk ornamentasi, trill berganti dua nada bertetangga, mordent kembali setelah satu tetangga, turn mengitari nada utama. Awal, durasi, dan penempatan hiasan berbeda menurut zaman/edisi; cari catatan edisi dan arahan pengajar. Tulis versi tanpa hiasan untuk mengenali harmoni dan pulsa, kemudian tambah hiasan tanpa memanjangkan birama tanpa alasan. Analisis sekuens, kadens, dan perubahan tonal membantu memilih arah serta memori.'),['Kontrapung: hubungan suara mandiri','Trill: pergantian nada tetangga','Sekuens: motif diulang pada tingkat lain'], 'Atas C4 D4 E4 F4 (1 2 3 4); bawah C3(2) G2(2) (5 5). Hias E4–F4–E4: 3–4–3, tetap dalam durasi E.', ['Nyanyikan tiap suara sendiri.','Mainkan sambil menonjolkan suara bawah lalu atas.','Tambah hiasan pada satu nada tanpa mengubah panjang birama.'], 'Rekam dua versi dua suara; analisis di mana motif berpindah dan bagaimana pendengar mengenalinya.', 'Hiasan menghilangkan pulsa: latih kerangka tanpa hiasan, bagi durasi, kemudian tambah perlahan.',q('Ornamentasi sebaiknya ditentukan…',['Dari gaya, edisi, dan konteks musik','Satu aturan universal','Selalu sebanyak mungkin'],0,'Konvensi hiasan berbeda; partitur dan sumber edisi membantu keputusan.'),[[48,60],62,[43,64],65,[48,67],65,[43,64],60],['L5 R1',2,'L5 R3',4,'L5 R5',4,'L5 R3',1]),
chapter('recital','Repertoar lanjut, resital, dan ensemble','Membangun program yang konsisten dengan kerja sama musikal.',[
'Teknik lanjut dipilih dari tuntutan karya: voicing akor tebal, lompatan, figurasi cepat, atau poliritme. Analisis gerak dengan pengajar dan cari versi potongan yang mempertahankan tujuan musik. Sonatina tidak otomatis mudah dan étude tidak otomatis wajib; tentukan rentang realistis dan prioritas berdasarkan kemampuan serta waktu.',
'Susun resital dengan karakter serta beban fisik yang bervariasi, latih jeda, awal setelah hening, dan akhir. Simulasi satu pengambilan membantu ketahanan serta pemulihan; beberapa penampilan hari berbeda menunjukkan konsistensi. Rencanakan istirahat dan jangan mengejar program panjang saat kontrol menurun.',
'Dalam duet/ensemble, baca partitur bersama, dengar suara lain, sepakati tempo, napas, artikulasi, dan isyarat masuk. Latih bagian pertemuan dan kadens dahulu. Sesudah bermain, pilih satu masalah komunikasi (misalnya masuk terlambat) dan satu masalah bunyi, lalu ubah menjadi latihan bersama. Evaluasi pengajar perlu mengamati interpretasi dan kenyamanan, yang tidak dapat dipastikan dari input MIDI.'
],['Ensemble: bermain bersama musisi','Resital: program penampilan','Isyarat masuk: komunikasi sebelum serangan'], 'Dua frasa tanya–jawab: C E G E | F A G C. R 1 2 4 2 | 1 3 2 1; bas C3 lalu F3. Beri satu napas sebelum frasa kedua.', ['Pilih program dua-tiga karya sesuai tingkat.','Latih awal/jeda/pemulihan dalam simulasi utuh.','Bermain duet sederhana, sepakati napas lalu rekam.'], 'Kumpulkan tiga rekaman program pada hari berbeda dan umpan balik pengajar yang spesifik.', 'Satu rekaman terbaik dianggap siap resital: uji ulang setelah jeda dan pada kondisi berbeda.',q('Kesiapan program dinilai dari…',['Beberapa penampilan utuh konsisten dan evaluasi','Tempo tangga nada saja','Jumlah chapter dibaca'],0,'Konsistensi musikal dan komunikasi lebih luas daripada satu angka teknik.'),[60,64,67,64,65,69,67,60],[1,2,4,2,1,3,2,1])]},
{id:'pop',title:'Jalur pop dan pengiring',requires:['practice'],legacy:7,criteria:'Aransemen pribadi utuh, transposisi untuk penyanyi, groove stabil, dan ruang untuk musisi lain.',human:true,chapters:[
chapter('groove','Lead sheet, chord chart, dan groove','Menjaga iringan sesuai birama dan vokal.',legacy[6].lessons[1].body.concat('Pada groove 4/4, dengarkan lokasi backbeat ketuk 2 dan 4; sinkopasi menempatkan serangan di antara pulsa. Di 3/4, pola bass–akor–akor memberi tiga langkah; di 6/8 enam seperdelapan umumnya dikelompokkan 3+3, dua pulsa besar. Chord chart memandu bentuk/akor tanpa menjamin ritme melodi. Mulai iringan satu serangan per birama, tambah hanya ketika vokal tetap jelas. Dengan backing track, dengarkan bass/drum dan jangan menambah bass yang bertabrakan.'),['Groove: hubungan ritme, aksen, dan rasa pulsa','Backbeat: aksen 2/4 dalam banyak pola pop','Chord chart: peta akor dan bagian'], '4/4 kiri C3 pada 1; kanan C4 E4 G4 pada 2/4. L5; R1-3-5. 6/8: bass pada 1 dan 4, nada lain pada 2–3/5–6.', ['Mainkan I–V–vi–IV satu akor tiap birama.','Tambah backbeat lalu satu sinkopasi tanpa mengubah pulsa.','Nyanyikan melodi sambil mengiringi; kurangi isi bila vokal tertutup.'], 'Buat chord chart intro–verse–chorus; coba pada 4/4 dan 6/8 dengan hitungan sesuai.', 'Banyak fill saat penyanyi bernyanyi: tempatkan fill pada ruang setelah frasa.',q('6/8 dalam pola umum mempunyai…',['Dua pulsa besar, masing-masing tiga seperdelapan','Selalu enam pulsa seperempat','Kecepatan wajib 68 BPM'],0,'Pengelompokan 3+3 berbeda dari tiga pulsa 3/4, meski total seperdelapan dapat sama.'),[[48,60,64,67],null,[60,64,67],null,[43,59,62,67],null,[59,62,67],null],['L5 R1-3-5',null,'R1-3-5',null,'L5 R1-2-5',null,'R1-2-5',null]),
chapter('arrange','Voicing, fill, intro, interlude, dan ending','Menyusun melodi dan akor menjadi aransemen solo.',[
'Mulai dari melodi sebagai suara atas, bass akar di kiri, dan satu-dua nada harmoni di tengah. Hindari akor padat terlalu rendah karena mudah keruh. Gunakan inversi agar suara tengah bergerak dekat. Fill dapat mengulang motif kecil setelah akhir frase; intro memperkenalkan tempo/tonalitas/motif; interlude memberi transisi; ending dapat memakai kadens, pengulangan motif, atau penutup ritmis yang disepakati.',
'Untuk solo, melodi harus tetap terdengar ketika akor hadir. Jika melodi G4 di atas C, susun C4 E4 G4 atau bass C3 dengan E4 G4. Penjarian 1–3–5 hanya usulan untuk posisi itu; ketika melodi berubah, sesuaikan agar sambungan nyaman. Cobalah satu versi jarang dan satu lebih penuh, rekam, lalu pilih berdasarkan arah frasa.',
'Transposisi untuk penyanyi dimulai dari rentang nyaman lagu, bukan hanya akor pertama. Pindahkan seluruh melodi, bass, dan akor menurut interval yang sama, lalu periksa kembali nada puncak. Dengan musisi lain, sepakati intro, jumlah pengulangan, interlude, dan isyarat ending. Latih transisi bagian sehingga aransemen menjadi karya utuh.'
],['Fill: isian di ruang frasa','Interlude: bagian penghubung','Voicing: susunan dan penonjolan suara akor'], 'Melodi G4 E4 D4 C4; bass C3 G2 F2 C3. Tambah nada tengah E4 saat G4, B3 saat D4. R awal 1+5 pada E4+G4, lalu ubah sesuai frasa.', ['Mainkan bass dan melodi saja.','Tambah satu suara tengah dengan gerak dekat.','Tulis intro 2 birama, interlude 2, ending 2, dan latih transisi.'], 'Susun aransemen 16–32 birama orisinal dan pindahkan ke tonalitas yang lebih nyaman untuk vokal.', 'Melodi hilang dalam akor: kurangi suara tengah dan latih nada atas dengan arah frase.',q('Transposisi untuk penyanyi harus memeriksa…',['Seluruh rentang melodi dan nada puncak','Hanya akor pertama','Jumlah tuts piano'],0,'Nada tertinggi/terendah menentukan kenyamanan vokal.'),[[48,64,67],[43,59,64],[41,57,62],[48,60,64]],['L5 R1-5','L5 R1-4','L5 R1-4','L5 R1-3']),
chapter('reharmonize','Reharmonisasi, medley, dan proyek pribadi','Mengganti harmoni dengan menjaga melodi dan bentuk.',[
'Reharmonisasi mengganti akor di bawah melodi yang sama. Mulai substitusi diatonik dengan nada bersama: di bawah E, C (C E G) dapat diganti Am (A C E) bila fungsi/frasa cocok. Uji bass, melodi, dan arah kadens, bukan sekadar akor terdengar menarik. Dominan sekunder dapat mengarah sementara ke akor tujuan, misalnya A7→Dm dalam C; C♯ di A7 mengarah ke D.',
'Pendalaman lanjut memakai borrowed chords, dominan sekunder berantai, dan perubahan bass dengan perhatian pada voice leading. Contoh F→Fm→C meminjam A♭ dari C minor untuk turun ke G; melodi yang memakai A natural perlu dievaluasi karena gesekan. Label akor tidak memberi izin mengabaikan melodi. Perkenalkan satu perubahan per versi dan bandingkan bunyi.',
'Medley menyambung beberapa tema dengan transisi tempo, tonalitas, dan bentuk yang jelas. Gunakan tema orisinal atau berizin. Rancang akor penghubung, isyarat masuk, serta durasi; uji dengan penyanyi/pemain lain. Proyek akhir: aransemen pribadi yang menunjukkan groove, voicing, intro, fill, transposisi, dan satu reharmonisasi yang dapat dijelaskan.'
],['Reharmonisasi: perubahan harmoni di bawah melodi','Dominan sekunder: dominan menuju akor selain tonika','Borrowed chord: akor pinjaman dari mode paralel'], 'Melodi E4(4) E4(4) F4(4) E4(4); bass C3→A2→D3→C3. Akor C→A7→Dm→C. R 1-3-5 untuk triad, susun A7 dekat dengan C♯.', ['Bandingkan C dan Am di bawah E yang sama.','Uji A7–Dm, jelaskan C♯ menuju D.','Buat dua tema orisinal lalu transisi medley 4 birama.'], 'Rekam versi awal dan reharmonisasi; tulis satu alasan perubahan dan satu tradeoff bunyi.', 'Substitusi merusak melodi: dengarkan nada melodi terhadap setiap akor dan revisi voicing.',q('A7 menuju Dm dalam C adalah…',['Dominan sekunder','Tonika C mayor','Akor tanpa terts'],0,'A7 memberi arah dominan ke Dm; C♯ mengarah ke D.'),[[48,60,64,67],[45,61,64,67],[50,62,65,69],[48,60,64,67]],['L5 R1-3-5','L5 R1-2-5','L5 R1-3-5','L5 R1-3-5'])]},
{id:'jazz',title:'Jalur jazz dan improvisasi',requires:['practice'],legacy:7,criteria:'Blues dan ii–V–I dengan bentuk stabil, motif berkembang, comping mendengar bass, dan permainan bersama.',human:true,chapters:[
chapter('blues','Swing, sinkopasi, dan blues 12-bar','Mengikuti bentuk sambil mengembangkan motif ritmis.',legacy[6].lessons[2].body.concat('Swing bukan satu rasio tetap. Pasangan seperdelapan sering tidak sama panjang, dengan rasa yang bergantung tempo/gaya; pembagian triplet panjang–pendek adalah latihan awal, bukan rumus universal. Tepuk pada 2 dan 4, nyanyikan motif lalu pindahkan ke piano. Blues 12-bar latihan di C: C7 C7 C7 C7 | F7 F7 C7 C7 | G7 F7 C7 G7. Tandai pergantian 4/5/9/12. Improvisasi mulai satu motif C–E♭–F, ubah ritme atau akhir, sisakan diam. Jangan hanya berlari tangga nada tanpa mengikuti bentuk.'),['Swing: rasa pembagian dan aksen jazz','Chorus: satu putaran bentuk','Motif: gagasan pendek untuk dikembangkan'], 'Motif C4 E♭4 F4 (R 1 2 3); jawab G4 F4 C4 (5 3 1). Shell C7: kiri C3 E3 B♭3, pecah rentang bila perlu.', ['Hitung 12 birama dengan bass akar.','Mainkan motif dan jawaban dengan diam satu birama.','Ubah ritme motif pada dua chorus tanpa kehilangan bentuk.'], 'Rekam tema dan dua chorus; tandai satu motif yang dikembangkan serta posisi perubahan akor.', 'Mengira swing selalu tepat 2:1: dengarkan konteks tempo/gaya dan latih phrasing dengan musisi.',q('Satu chorus blues latihan ini berarti…',['Satu putaran 12 birama','Satu nada panjang','Hanya bagian chorus lagu pop'],0,'Dalam improvisasi, chorus adalah satu putaran bentuk yang sedang dimainkan.'),[60,63,65,null,67,65,60,null],[1,2,3,null,5,3,1,null]),
chapter('voicings','ii–V–I, guide tones, shells, dan extensions','Mengatur suara penentu akor sambil mendengar bass.',[
'ii–V–I mayor di C: Dm7–G7–Cmaj7. Minor di C: Dm7♭5–G7(♭9)–Cm(maj7) atau Cm6 menurut konteks. Guide tones terts dan ketujuh menjelaskan kualitas/fungsi: Dm7 F–C, G7 F–B, Cmaj7 E–B. C→B dan F→E membuat perpindahan terdengar dekat. Latih dua suara ini dahulu, kemudian tambah bass akar.',
'Shell voicing memakai akar serta terts/ketujuh dengan susunan ringkas. Rootless voicing menghilangkan akar ketika bass/pemain lain menyediakan dasar: Dm9 F A C E; G13 F A B E; Cmaj9 E G B D sebagai satu kemungkinan. Gunakan register tengah dan perhatikan nada bersama. Extensions 9/11/13 serta alterations ♭9/♯9/♯11/♭13 memberi warna; pilih sesuai melodi serta fungsi, jangan menumpuk semua.',
'Comping adalah iringan ritmis yang merespons solois dan rhythm section. Dengarkan bass, hindari menggandakan register/ritme tanpa tujuan, beri ruang setelah frase solois. Mulai satu serangan per birama kemudian tambahkan serangan sinkopasi yang jelas. Dalam solo piano, akar mungkin perlu hadir lebih sering; rootless bukan kewajiban.'
],['Guide tones: terts dan ketujuh penentu fungsi','Shell: voicing ringkas','Rootless: susunan tanpa akar','Comping: iringan ritmis responsif'], 'Dm7 F3 C4 → G7 F3 B3 → Cmaj7 E3 B3. L awal 1+5 dapat dibalik sesuai rentang; coba R 1+5 pada pasangan. Tambah bass D2 G2 C3 terpisah.', ['Mainkan guide tones saja dan nyanyikan gerak setengah nada.','Tambah akar lalu rootless dengan bass terpisah.','Coba ii–V–I C/F/G dan minor C; comping dengan ruang diam.'], 'Rekam tiga tonalitas dengan melodi chord tones; jelaskan nada yang berubah dan peran bass.', 'Rootless terdengar tanpa dasar saat solo: tambah akar/struktur bass secara terencana.',q('Guide tones utama dalam akor tujuh adalah…',['Terts dan ketujuh','Akar dan kuint saja','Selalu 9 dan 13'],0,'Keduanya menegaskan kualitas dan arah voice leading, misalnya C→B dan F→E.'),[[53,60],[53,59],[52,59],[53,59],[53,56],[51,59]],['1+5','1+5','1+5','1+5','1+3','1+5']),
chapter('improv','Improvisasi, transkripsi, modal, dan ensemble','Mengembangkan kosakata pribadi dengan motif dan pendengaran.',[
'Mulai improvisasi dengan ritme: satu nada, satu motif, pertanyaan-jawaban, lalu chord tones pada perubahan akor. Di Dm7–G7–Cmaj7, arahkan C pada Dm7 menuju B pada G7, lalu E pada Cmaj7; gunakan nada penghubung di antara tujuan. Chord–scale membantu memilih warna, tetapi bentuk, ritme, motif, dan voice leading tetap mengarahkan cerita.',
'Transkripsi pendek berarti mendengar, menyanyikan, memainkan, lalu menganalisis potongan yang penggunaannya diizinkan. Gunakan improvisasi sendiri atau rekaman berlisensi sesuai izin; jangan menyalin solo penuh berhak cipta tanpa izin. Pilih 1–2 birama, identifikasi ritme/target nada, pindahkan ke dua tonalitas, kemudian ubah menjadi kalimatmu. Menyalin tanpa memahami fungsi tidak memberi kosakata fleksibel.',
'Modal jazz dapat bertahan pada satu pusat/mode lebih lama: contoh D Dorian D E F G A B C. Bangun motif dengan ruang dan warna, jangan merasa perlu memainkan semua nada. Reharmonisasi ii–V–I dapat memperkenalkan tritone substitution D♭7 untuk G7: guide tones F dan C♭(B) berkaitan; periksa bass/melodi sebelum memakai. Bermain bersama musisi melatih respons, masuk bentuk, pertukaran frase, dan komunikasi yang skor otomatis tidak ukur.'
],['Dorian: minor dengan tingkat 6 mayor','Tritone substitution: dominan berjarak triton','Transkripsi: mencatat musik yang didengar'], 'Target ii–V–I: C4→B3→E4 (R 3→2→5); isi D4 C4 B3 D4 E4 (4 3 2 4 5). Modal D: D4 F4 A4 B4 (1 2 4 5).', ['Improvisasi satu motif pada dua chorus.','Transkripsi satu frase sendiri dan transposisikan.','Coba Dorian lalu bandingkan G7/D♭7; bermain dengan bass/pemain lain.'], 'Rekam improvisasi, tandai motif/target/diam, lalu minta umpan balik ritme dan komunikasi.', 'Menggunakan scale untuk setiap ketuk: batasi tiga nada, beri diam, arahkan ke chord tone.',q('Chord–scale dalam improvisasi adalah…',['Salah satu alat bersama ritme, motif, dan voice leading','Satu-satunya pendekatan','Pengganti mendengar pemain lain'],0,'Pilihan nada saja belum membentuk kalimat atau interaksi musikal.'),[62,60,59,62,64,null,62,65,69,71],[4,3,2,4,5,null,1,2,4,5])]},
{id:'advanced',title:'Pendalaman menuju expert',requires:['practice'],legacy:8,human:true,criteria:'Beberapa program/rekaman utuh pada hari berbeda, repertoar luas sesuai jalur, karya kreatif/ensemble, dan evaluasi berkala pengajar.',chapters:[
chapter('individual','Teknik individual, lapisan suara, dan partitur kompleks','Menyusun pendalaman berdasarkan kebutuhan pribadi.',[
'Pilih jalur utama lalu audit kebutuhan dari repertoar nyata: garis dalam yang tenggelam, lompatan luas, figurasi rapat, poliritme, atau membaca tekstur baru. Kecilkan menjadi unit yang mempertahankan masalah musik. Misalnya pada tiga lapisan, mainkan melodi dan bass dulu, tambahkan suara dalam lembut, lalu uji apakah masing-masing dapat ditonjolkan. Latih ketahanan lewat jeda dan rotasi tugas, bukan terus bermain saat kualitas menurun.',
'Partitur kompleks dibaca dengan mengelompokkan harmoni, motif, suara, dan titik serangan bersama. Tandai perubahan kunci/meter dan pembagian tangan; coba pengurangan tekstur sebelum seluruh not. Untuk poliritme 3:2, petakan enam subdivisi: tiga serangan pada 0/2/4, dua pada 0/3. Ini latihan awal koordinasi, bukan seluruh interpretasi poliritme. Naikkan tuntutan dengan pendampingan sesuai karya.',
'Penjarian, redistribusi tangan, pedal, serta tempo perlu mempertimbangkan ukuran tangan, instrumen, akustik, dan gaya. Pengajar/pianis berpengalaman dapat mengamati gerak serta bunyi yang tidak diukur website. Kurikulum memberi prosedur latihan; keterampilan expert berkembang bertahun-tahun lewat repertoar luas, pengalaman bermain, dan evaluasi berulang. Menyelesaikan chapter tidak otomatis menghasilkan status expert.'
],['Redistribusi: pembagian nada ulang antartangan','Poliritme: pembagian ritme berbeda bersamaan','Lapisan suara: melodi, dalam, dan bass'], '3:2 enam subdivisi: R C4 E4 G4 pada 0/2/4 (1/3/5); L C3 G3 pada 0/3 (5/1). Hitung subdivisi dahulu, lalu dengarkan pulsa besar.', ['Audit satu masalah dalam karya lanjut.','Kurangi tekstur lalu tambah suara satu lapisan setiap kali.','Tunjukkan potongan/gerak pada pengajar sebelum meningkatkan tuntutan.'], 'Buat rencana 12 minggu dengan tiga fokus pribadi dan bukti awal dari karya pilihan.', 'Menyamakan BPM tinggi dengan expert: evaluasi bunyi, konsistensi, interpretasi, komunikasi, dan kenyamanan.',q('Website dapat memastikan dari MIDI…',['Identitas nada/serangan dalam batas alat, bukan postur atau interpretasi','Seluruh teknik fisik','Status expert'],0,'MIDI tidak mengamati tubuh, ketegangan, atau alasan musikal.'),[[48,60],64,55,67,60,64],['L5 R1','R3','L1','R5','R1','R3']),
chapter('independent','Analisis mendalam, memori, dan karya kreatif','Memperbaiki masalah secara mandiri dan mempertanggungjawabkan interpretasi.',[
'Analisis mendukung latihan ketika terhubung ke keputusan: perubahan harmoni menuju kadens menentukan arah, sekuens membantu memori transposisi, dan bentuk menentukan kembali tema. Tulis peta tema, tonalitas, tekstur, puncak, serta titik jangkar; uji memulai dari beberapa lokasi tanpa awalan. Bandingkan edisi/sumber yang sah dan jelaskan keputusan artikulasi serta pedal dengan bunyi yang dihasilkan.',
'Bangun repertoar luas dalam jalurmu: karya kontras, beberapa rentang tekstur, pengalaman solo dan bersama musisi. Luas tidak berarti mengumpulkan judul yang pernah disentuh; pelihara beberapa karya yang dapat ditampilkan utuh. Pilih proyek improvisasi, aransemen, atau komposisi dengan bentuk dan sasaran yang jelas. Revisi berdasarkan rekaman dan tanggapan pendengar.',
'Kemandirian berarti mampu menguji hipotesis: identifikasi masalah, pilih metode, ukur perubahan, dan revisi. Tetap minta bantuan ketika nyeri, masalah gerak menetap, atau interpretasi memerlukan perspektif baru. Dokumentasikan dua pendekatan dan alasan memilihnya. Evaluasi berkala menghubungkan refleksi pribadi dengan standar musikal yang diamati orang berpengalaman.'
],['Hipotesis latihan: dugaan metode yang akan memperbaiki masalah','Analisis bentuk: hubungan bagian musik','Portofolio: kumpulan bukti permainan dan karya'], 'Motif C E G → D F A → E G B. R 1-3-5 tiap posisi dengan perpindahan; jadikan tema A, ubah ritme menjadi B, kembalikan A.', ['Buat peta harmoni/bentuk karya.','Uji memori dari lima jangkar dan catat yang rapuh.','Ciptakan tema/aransemen, revisi satu aspek berdasarkan rekaman.'], 'Siapkan portofolio karya utuh dan karya kreatif dengan catatan sumber/izin serta alasan interpretasi.', 'Analisis hanya nama akor: tulis dampaknya pada arah, latihan, dan memori, lalu uji bunyinya.',q('Analisis paling berguna ketika…',['Mengubah keputusan latihan, memori, atau interpretasi','Hanya daftar label','Menggantikan bermain musik'],0,'Analisis harus membantu hasil yang terdengar dan dapat diuji.'),[60,64,67,62,65,69,64,67,71],[1,3,5,1,3,5,1,3,5]),
chapter('portfolio','Penampilan konsisten dan evaluasi berkelanjutan','Membangun bukti kesiapan melalui program, ensemble, dan umpan balik.',old(8,2).concat('Kumpulkan paling sedikit tiga penampilan/rekaman utuh pada hari berbeda untuk evaluasi konsistensi tahap ini. Sertakan program, konteks, tanggal, gangguan, dan pemulihan, bukan hanya tautan pengambilan terbaik. Pengajar menilai kejelasan lapisan, frase, pedal, ketahanan, interpretasi, dan gerak. Website mencatat umpan balik yang dilaporkan pengguna; identitas pengajar tidak diverifikasi. Jangan memakai jumlah chapter, kecepatan tangga nada, atau skor otomatis sebagai definisi expert. Sesudah penampilan, pilih satu perbaikan, satu hal untuk dipelihara, dan proyek berikutnya bersama musisi.'),['Konsistensi: kualitas berulang dalam beberapa kondisi','Evaluasi manusia: pengamatan pengajar/pianis berpengalaman','Ketahanan: kemampuan mempertahankan kontrol dengan istirahat sesuai'], 'Program: karya pembuka, kontras, penutup; gunakan peta jangkar dan penjarian tiap karya. Demo C–F–G–C menunjukkan arah kadens, bukan seluruh tuntutan program lanjut.', ['Simulasikan program utuh dengan jeda realistis.','Kumpulkan tiga rekaman hari berbeda dan refleksi.','Minta evaluasi berkala, ubah temuan menjadi siklus latihan berikut.'], 'Serahkan portofolio utuh, pengalaman ensemble, refleksi dan umpan balik pengajar; lanjutkan pendalaman bertahun-tahun.', 'Mengejar satu skor sebagai gelar: bahas kriteria kualitas serta keterbatasan bukti dengan pengajar.',q('Kelulusan kurikulum berarti…',['Bukti belajar terpenuhi menurut evaluasi yang dicatat; bukan gelar expert','Otomatis expert semua gaya','Tidak perlu bimbingan lagi'],0,'Expert memerlukan perkembangan jangka panjang, repertoar, pengalaman, dan evaluasi manusia.'),[[48,60,64,67],[53,60,65,69],[55,59,62,67],[48,60,64,67]],['L5 R1-3-5','L5 R1-3-5','L5 R1-2-5','L5 R1-3-5'])]}
];

